package com.fasttravel.dao.impl;import com.fasttravel.dao.UserDAO;import com.fasttravel.entity.User;import com.fasttravel.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Repository;import java.util.*;
@Repository @RequiredArgsConstructor public class UserDAOImpl implements UserDAO{private final UserRepository repo;public User save(User e){return repo.save(e);}public Optional<User> findById(Long id){return repo.findById(id);}public List<User> findAll(){return repo.findAll();}public void deleteById(Long id){repo.deleteById(id);}public Optional<User> findByEmail(String email){return repo.findByEmailIgnoreCase(email);}public boolean exists(String email,String phone){return repo.existsByEmailIgnoreCaseOrPhone(email,phone);}}
